css_override_blueprint_for_vibrant_ui_cs.css_rules:
/* Home Exam Cards - Wine + Ivory + Black Buttons Override */
.bold-exam-card,
.bold-exam-card.exam-tone-jee-main,
.bold-exam-card.exam-tone-bitsat,
.bold-exam-card.exam-tone-comedk {
  background: linear-gradient(155deg, #2E0911 0%, #20050A 55%, #150306 100%) !important;
  border: 1px solid #581622 !important;
  box-shadow: inset 0 1px 0 rgba(255, 235, 225, 0.12), 0 18px 40px rgba(18, 2, 5, 0.70) !important;
  color: #FAF4ED !important;
  border-radius: 18px !important;
  transition: border-color 220ms ease, box-shadow 220ms ease, transform 220ms ease !important;
}

.bold-exam-card:hover,
.bold-exam-card.exam-tone-jee-main:hover,
.bold-exam-card.exam-tone-bitsat:hover,
.bold-exam-card.exam-tone-comedk:hover {
  border-color: #8B2032 !important;
  box-shadow: inset 0 1px 0 rgba(255, 235, 225, 0.18), 0 22px 50px rgba(139, 32, 50, 0.25), 0 18px 40px rgba(18, 2, 5, 0.85) !important;
  transform: translateY(-2px) !important;
}

/* Card Headings & Typography */
.bold-exam-card h2,
.bold-exam-card h2 a,
.bold-exam-card.exam-tone-bitsat h2,
.bold-exam-card.exam-tone-bitsat h2 a {
  color: #FAF4ED !important;
  font-weight: 800 !important;
}

.bold-exam-card p,
.bold-exam-card .exam-meta,
.bold-exam-card .exam-subtitle {
  color: #D8C7C1 !important;
}

/* Card Eyebrows & Badges */
.bold-exam-card .exam-badge,
.bold-exam-card .eyebrow {
  background: #421019 !important;
  color: #F3E5E1 !important;
  border: 1px solid #6D1B2A !important;
}

/* Black Buttons inside Wine Cards */
.bold-exam-card .exam-primary,
.bold-exam-card.exam-tone-bitsat .exam-primary,
.bold-exam-card .jeelive-button {
  background: #08080A !important;
  color: #FAF4ED !important;
  border: 1px solid #4A1520 !important;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.50) !important;
  font-weight: 750 !important;
}

.bold-exam-card .exam-primary:hover,
.bold-exam-card.exam-tone-bitsat .exam-primary:hover,
.bold-exam-card .jeelive-button:hover {
  background: #14141A !important;
  color: #FFFFFF !important;
  border-color: #782030 !important;
  box-shadow: 0 8px 22px rgba(0, 0, 0, 0.70), 0 0 12px rgba(120, 32, 48, 0.30) !important;
}
